package net.civeira.phylax.features.access.userverificationcode.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.SecretDigester;

class CodeHashVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property code hash of user verification code ")
  void test_code_hash_v_o_builder() {
    SecretDigester service = Mockito.mock(SecretDigester.class);
    Mockito.when(service.digest("small")).thenReturn("hmac-sha256:p0:example");
    Assertions.assertEquals("hmac-sha256:p0:example",
        CodeHashVO.fromPlain("small").getCodeHashStored(service).orElse(null));
    Assertions.assertEquals("****", CodeHashVO.fromPlain("small").toString());
  }
}
